export type Verdict = 'hit' | 'partial' | 'miss'
export type Counts = { read: string; wrote: string; input: number; output: number }

type SpanWords = {
  units: Record<'s' | 'm' | 'h', string>
  /** Clock minutes may use a shorter word than a whole length of time. */
  clockMinute?: string
  join?: string
  space?: boolean
  decimal?: string
  /** Duration nouns precede their counts in some languages, including both parts of a clock. */
  unitFirst?: boolean
}

/** The formatters keep time compact; sentences need the language's units and punctuation. */
export function makeSpan({ units, clockMinute = units.m, join = ' ', space = true, decimal = '.', unitFirst = false }: SpanWords) {
  const gap = space ? ' ' : ''
  const withUnit = (amount: string, unit: string) => {
    const number = amount.replace('.', decimal)

    return unitFirst ? `${unit}${gap}${number}` : `${number}${gap}${unit}`
  }

  return (text: string): string => {
    const clock = /^(\d+):(\d\d)$/.exec(text)
    if (clock) {
      const [, minutes = '', seconds = ''] = clock

      return Number(seconds) === 0
        ? withUnit(minutes, units.m)
        : `${withUnit(minutes, clockMinute)}${join}${withUnit(String(Number(seconds)), units.s)}`
    }
    const [, amount, unit] = /^(\d+(?:\.\d+)?)([smh])$/.exec(text) ?? []

    return amount === undefined ? text : withUnit(amount, units[unit as keyof typeof units])
  }
}

files.types/index.d.ts:
export type Ttl = '5m' | '1h'

/** What one keep-alive ping reported, as the API counted it. */
export type PingUsage = {
  at: number
  read: number
  created: number
  input: number
  output: number
}

/** The main conversation's prompt cache as the last touch left it. */
export type Snapshot = {
  /** Start of the last request that read or wrote the cache, in ms since the epoch. */
  touchedAt: number
  touchedBy: 'turn' | 'ping' | 'resume'
  /** Start of the last request the conversation itself made; pings do not move it. */
  turnAt: number
  /** Keep-alives sent since `turnAt`: what the auto budget counts. */
  pingsSinceTurn: number
  /** Tokens the cache holds for the main conversation's prefix. */
  cachedTokens: number
  /** The model id the API reported; caches are per model. */
  model: string
  ttl: Ttl
  /** Where `ttl` came from: the environment, an observed hit or miss, or the default for the billing mode. */
  ttlSource: 'env' | 'observed' | 'assumed'
  /** Why the cache is unusable whatever the clock says, or null. */
  coldReason: string | null
  lastPing: PingUsage | null
}

/** The auto keep-alive switch, per session: off until the person turns it on. */
export type Auto = {
  isOn: boolean
  /** The most pings one idle stretch may spend, before the break-even count lowers it. */
  cap: number
}

declare module 'claude-code' {
  interface PluginState {
    'cache-refresher': { snapshot: Snapshot | null; auto: Auto }
  }
}
